input.new_string:
  try {
    for (const statement of readMigrationStatements()) {
      sqlite.exec(statement);
    }
    ensureRecountedAtColumn(sqlite);
  } finally {
    sqlite.close();
  }
}

/**
 * `CREATE TABLE IF NOT EXISTS` will not add a column to a database that
 * already has `organization_usage`. The recount queue reads `recounted_at`,
 * so an older file still has to grow that column.
 */
function ensureRecountedAtColumn(sqlite: Database): void {
  const table = sqlite
    .prepare(
      "SELECT name FROM sqlite_master WHERE type = 'table' AND name = 'organization_usage'",
    )
    .get();
  if (!table) return;

  const columns = sqlite.prepare("PRAGMA table_info(organization_usage)").all() as readonly {
    name: string;
  }[];
  if (columns.some((column) => column.name === "recounted_at")) return;
  sqlite.exec("ALTER TABLE organization_usage ADD COLUMN recounted_at TEXT");
}

