import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const dir = mkdtempSync(join(tmpdir(), "tf-queue-"));
const path = join(dir, "taskflow.db");
process.env.TASKFLOW_DB_PATH = path;

const { runMigrations } = await import(
  "/private/tmp/bench-scratch/593391f9-a3af-413d-b369-afe247e5c4b9/src/server/db/migrate.ts"
);
await runMigrations(path);

const orgRepo = await import(
  "/private/tmp/bench-scratch/593391f9-a3af-413d-b369-afe247e5c4b9/src/server/repositories/organization-repository.ts"
);
const usageRepo = await import(
  "/private/tmp/bench-scratch/593391f9-a3af-413d-b369-afe247e5c4b9/src/server/repositories/usage-repository.ts"
);
const userRepo = await import(
  "/private/tmp/bench-scratch/593391f9-a3af-413d-b369-afe247e5c4b9/src/server/repositories/user-repository.ts"
);
const { runUsageRollupJob } = await import(
  "/private/tmp/bench-scratch/593391f9-a3af-413d-b369-afe247e5c4b9/src/server/jobs/usage-rollup-job.ts"
);
const { runOverdueIssueJob, resetOverdueTracking } = await import(
  "/private/tmp/bench-scratch/593391f9-a3af-413d-b369-afe247e5c4b9/src/server/jobs/overdue-issue-job.ts"
);
const issueRepo = await import(
  "/private/tmp/bench-scratch/593391f9-a3af-413d-b369-afe247e5c4b9/src/server/repositories/issue-repository.ts"
);
const projectRepo = await import(
  "/private/tmp/bench-scratch/593391f9-a3af-413d-b369-afe247e5c4b9/src/server/repositories/project-repository.ts"
);
const { subscribe } = await import(
  "/private/tmp/bench-scratch/593391f9-a3af-413d-b369-afe247e5c4b9/src/lib/event-bus.ts"
);
const { getDb } = await import(
  "/private/tmp/bench-scratch/593391f9-a3af-413d-b369-afe247e5c4b9/src/server/db/client.ts"
);
const { organizationUsage } = await import(
  "/private/tmp/bench-scratch/593391f9-a3af-413d-b369-afe247e5c4b9/src/server/db/schema/organizations.ts"
);
const { eq } = await import("drizzle-orm");

const owner = await userRepo.insertUser({
  email: "o@test",
  name: "Owner",
  passwordHash: "x",
});

const ids: string[] = [];
for (let i = 0; i < 30; i += 1) {
  const org = await orgRepo.insertOrg(
    { name: `Org ${i}`, slug: `org-${i}`, plan: "growth" },
    owner.id,
  );
  ids.push(org.id);
  const when = new Date(Date.UTC(2020, 0, 1 + i)).toISOString();
  getDb()
    .insert(organizationUsage)
    .values({
      orgId: org.id,
      seatsUsed: 0,
      projectsUsed: 0,
      issuesUsed: 99,
      storageMbUsed: 0,
      measuredAt: when,
      recountedAt: when,
    })
    .run();
}

const deleted = await orgRepo.insertOrg(
  { name: "Gone", slug: "gone", plan: "growth" },
  owner.id,
);
await orgRepo.archiveOrg(deleted.id);
getDb()
  .insert(organizationUsage)
  .values({
    orgId: deleted.id,
    seatsUsed: 0,
    projectsUsed: 0,
    issuesUsed: 99,
    storageMbUsed: 0,
    measuredAt: "2010-01-01T00:00:00.000Z",
    recountedAt: "2010-01-01T00:00:00.000Z",
  })
  .run();

const before = await usageRepo.listOrgIdsForRollup(25);
const expectedFirst = ids.slice(0, 25);
if (before.join() !== expectedFirst.join()) {
  console.error("FIRST PASS ORDER", before, expectedFirst);
  process.exit(1);
}
if (before.includes(deleted.id)) {
  console.error("deleted org in rollup queue");
  process.exit(1);
}

const bumped = ids[0]!;
const placeBefore = (await usageRepo.listOrgIdsForRollup(30)).join();
await usageRepo.incrementUsage(bumped as never, { issuesUsed: 1 });
const placeAfter = (await usageRepo.listOrgIdsForRollup(30)).join();
if (placeBefore !== placeAfter) {
  console.error("increment moved the queue");
  console.error(placeBefore);
  console.error(placeAfter);
  process.exit(1);
}

const row = getDb()
  .select()
  .from(organizationUsage)
  .where(eq(organizationUsage.orgId, bumped))
  .get();
if (row?.recountedAt !== "2020-01-01T00:00:00.000Z") {
  console.error("increment changed recountedAt", row);
  process.exit(1);
}
if (row.issuesUsed !== 100) {
  console.error("increment did not apply", row);
  process.exit(1);
}

const result = await runUsageRollupJob(new Date("2026-06-01T00:00:00.000Z"));
if (result.processed !== 25) {
  console.error("processed", result);
  process.exit(1);
}

const after = await usageRepo.listOrgIdsForRollup(30);
const expectedNext = [...ids.slice(25), ...ids.slice(0, 25)];
if (after.join() !== expectedNext.join()) {
  console.error("SECOND PASS ORDER");
  console.error("got ", after);
  console.error("want", expectedNext);
  process.exit(1);
}

const recounted = getDb()
  .select()
  .from(organizationUsage)
  .where(eq(organizationUsage.orgId, ids[0]!))
  .get();
const untouched = getDb()
  .select()
  .from(organizationUsage)
  .where(eq(organizationUsage.orgId, ids[29]!))
  .get();
if (recounted?.issuesUsed !== 0) {
  console.error("oldest was not recounted", recounted);
  process.exit(1);
}
if (untouched?.issuesUsed !== 99) {
  console.error("newest was recounted too soon", untouched);
  process.exit(1);
}

const second = await runUsageRollupJob(new Date("2026-06-02T00:00:00.000Z"));
if (second.processed !== 5) {
  console.error("second pass should finish the remaining 5, got", second.processed);
  process.exit(1);
}
const newest = getDb()
  .select()
  .from(organizationUsage)
  .where(eq(organizationUsage.orgId, ids[29]!))
  .get();
if (newest?.issuesUsed !== 0) {
  console.error("second pass missed the tail", newest);
  process.exit(1);
}

const project = await projectRepo.insertProject(
  { orgId: deleted.id as never, name: "P", slug: "p", key: "P" },
  owner.id,
);
const number = await issueRepo.nextIssueNumber(deleted.id as never, project.id);
await issueRepo.insertIssue(
  {
    orgId: deleted.id as never,
    projectId: project.id,
    title: "Late",
    dueAt: "2020-01-01T00:00:00.000Z",
  } as never,
  owner.id,
  number,
);

const live = await orgRepo.insertOrg(
  { name: "Live late", slug: "live-late", plan: "growth" },
  owner.id,
);
const liveProject = await projectRepo.insertProject(
  { orgId: live.id, name: "LP", slug: "lp", key: "LP" },
  owner.id,
);
const liveNumber = await issueRepo.nextIssueNumber(live.id, liveProject.id);
const liveIssue = await issueRepo.insertIssue(
  {
    orgId: live.id,
    projectId: liveProject.id,
    title: "Live late",
    dueAt: "2020-01-01T00:00:00.000Z",
  } as never,
  owner.id,
  liveNumber,
);

resetOverdueTracking();
const seen: string[] = [];
subscribe("issue.overdue", (payload) => {
  seen.push(payload.orgId);
});
await runOverdueIssueJob(new Date("2026-06-01T00:00:00.000Z"));
if (seen.includes(deleted.id)) {
  console.error("deleted org got an overdue alert", seen);
  process.exit(1);
}
if (!seen.includes(live.id)) {
  console.error("live org missed overdue", seen, liveIssue.id);
  process.exit(1);
}

console.log("ok", { liveOrgs: (await orgRepo.listLiveOrgIds()).length, seen });
rmSync(dir, { recursive: true, force: true });

